insert into public.reg_pack (id, version, published_at, notes) values ('texas-2026-09-01', 2, '2026-09-01T12:00:00Z', 'Texas (TPWD Outdoor Annual 2026-2027, valid Sep 1 2026–Aug 31 2027): FULL saltwater digest (v2) — every per-species page in the Annual''s saltwater bag/length section is encoded here with its own clause text. 2026-27 red snapper federal season flagged check-in-season. Tags (Red Drum Tag, Spotted Seatrout Tag) quoted, not modeled.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

