insert into public.reg_pack (id, version, published_at, notes) values ('louisiana-2026-09-01', 2, '2026-09-01T12:00:00Z', 'Louisiana (LDWF 2025 Recreational Fishing Regulations booklet, updated Aug 20 2025): v2 = FULL saltwater digest — the 2024 redfish/trout reset plus the complete reef/HMS/shark tables, the October-November flounder possession closure, and the ROLP note. State-managed red snapper is check-in-season.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

insert into public.reg_rule
  (species_id, reg_group_id, reg_area_id, water_class, kind, verbatim, source_url, source_title, source_updated_at, verified_at, pack_version,
   season_start, season_end, bag_daily, possession_limit, min_size_in, max_size_in, size_measure, platform_scope, depth_note, check_inseason, stale_after_days)
values
  ('spotted_seatrout', null, 'la-gulf', 'salt', 'bag_limit', 'SPOTTED SEATROUT (Speckled Trout): 13” min total length, 20” max total length; 15 daily per person with no more than 2 over 20” max total length. Retention by captain and crew on charter or head boats while on a for-hire trip is prohibited. Take or possession of spotted seatrout in federal waters: same limits as state.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-02-04', '2026-09-02', 1,
   null, null, 15, 30, 13, 20, 'total_length', null, 'Slot: no more than 2 over 20” inside the 15-fish creel; for-hire captain/crew creel = 0.', false, 60),
  ('red_drum', null, 'la-gulf', 'salt', 'bag_limit', 'RED DRUM (Redfish): 18” min total length; 27” max total length; 4 daily per person. No retention allowance for fish over 27 inches. Retention by captain and crew on charter or head boats while on a for-hire trip is prohibited. Take or possession of red drum in federal waters is prohibited.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-02-04', '2026-09-02', 1,
   null, null, 4, 8, 18, 27, 'total_length', null, 'Fed-waters take prohibited; for-hire captain/crew creel = 0.', false, 60),
  ('black_drum', null, 'la-gulf', 'salt', 'bag_limit', 'BLACK DRUM: 16” min total length; 5 daily per person; no more than 1 over 27” (max TL) may be kept. Possession limit is twice the daily creel limit unless otherwise stated.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-02-04', '2026-09-02', 1,
   null, null, 5, 10, 16, 27, 'total_length', null, 'One >27” bull counts inside the 5-fish creel.', false, 60),
  ('sheepshead', null, 'la-gulf', 'salt', 'bag_limit', 'SHEEPSHEAD: 10 daily per person; 12” min total length (12” fork-length conversions in older tables refer to fork length).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-02-04', '2026-09-02', 1,
   null, null, 10, 20, 12, null, 'total_length', null, null, false, 60),
  ('southern_flounder', null, 'la-gulf', 'salt', 'bag_limit', 'SOUTHERN FLOUNDER: 10 daily per person; No Size Limit; NO possession allowed from Oct. 15 - Nov. 30.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet, Saltwater State Creel & Size Limits)', '2025-08-20', '2026-09-02', 1,
   null, null, 10, 20, null, null, null, null, 'Flounder possession banned Oct 15–Nov 30.', false, 60),
  ('southern_flounder', null, 'la-gulf', 'salt', 'season', 'SOUTHERN FLOUNDER: No possession allowed from Oct. 15 - Nov. 30 (10 daily per person, no size limit, outside the closure).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   '2026-10-15', '2026-11-30', null, null, null, null, null, null, null, false, 60),
  ('red_snapper', null, 'la-gulf', 'salt', 'note', 'RED SNAPPER: 16” min total length; 4 daily per person (subject to change mid-season — the LDWF booklets marks this row footnotes 10 & 11 exactly so). Louisiana runs private red snapper seasons under state management and announces openings/closures against the state quota; verify the current season notice (LDWF red snapper page) before each trip.', 'https://www.wlf.louisiana.gov/page/red-snapper', 'LDWF — Red Snapper', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, 'Season announced against quota; check LDWF before each trip.', true, 14),
  ('greater_amberjack', null, 'la-gulf', 'salt', 'bag_limit', 'AMBERJACK, GREATER: 34” min fork length; 1 daily per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-02-04', '2026-09-02', 1,
   null, null, 1, 2, 34, null, 'fork_length', null, null, false, 60),
  ('gray_triggerfish', null, 'la-gulf', 'salt', 'bag_limit', 'GRAY TRIGGERFISH: 15” min fork length; 1 daily per person in aggregate (reef fish aggregate rules apply in federal waters as posted by the Gulf Council).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-02-04', '2026-09-02', 1,
   null, null, 1, 2, 15, null, 'fork_length', null, null, false, 60),
  ('atlantic_tarpon', null, 'la-gulf', 'salt', 'note', 'Tarpon — summarized, not quoted: Louisiana treats tarpon harvest as effectively tag-limited and unusual; the in-practice rule is catch-and-release. Any retention requires confirming a current LDWF tarpon rule/tags before keeping.', 'https://www.wlf.louisiana.gov/page/recreational-saltwater-fishing', 'LDWF — Recreational saltwater fishing', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 30),
  (null, null, 'la-gulf', 'salt', 'note', 'Possession limit is TWICE the daily creel limit unless otherwise stated. Recreational saltwater anglers may possess a two days’ bag limit on land; no person shall be in possession of fish over the daily bag limit in any one day or while fishing or while on the water.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-02-04', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 60),
  ('cobia', null, 'la-gulf', 'salt', 'bag_limit', 'COBIA (Ling or Lemonfish): 1 daily per person; 36” min fork length; no more than 2 per vessel.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 1, 2, 36, null, 'fork_length', null, '≤2 per vessel.', false, 60),
  ('king_mackerel', null, 'la-gulf', 'salt', 'bag_limit', 'KING MACKEREL: 24” min fork length; 3 daily per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 3, 6, 24, null, 'fork_length', null, null, false, 60),
  ('spanish_mackerel', null, 'la-gulf', 'salt', 'bag_limit', 'SPANISH MACKEREL: 12” min fork length; 15 daily per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 15, 30, 12, null, 'fork_length', null, null, false, 60),
  ('striped_mullet', null, 'la-gulf', 'salt', 'note', 'STRIPED MULLET: No Size Limit; 100 lbs. daily.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, 'Limit is by weight, not fish count.', false, 60),
  (null, null, 'la-gulf', 'salt', 'bag_limit', 'GROUPER: Black & Gag — 24” min total length; Red & Yellowfin — 20” min total length; Scamp — 16” min total length. 4 daily in aggregate; no more than 1 speckled hind and 1 Warsaw grouper per vessel, not more than 2 red grouper per person, and not more than 2 gag per person included in the bag limit. Goliath & Nassau: Take Prohibited — Take/Possession Prohibited.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 4, 8, null, null, null, null, 'Aggregate ceiling quoted; per-species caps below.', false, 60),
  ('gag_grouper', null, 'la-gulf', 'salt', 'bag_limit', 'Gag grouper: 24” min total length; no more than 2 gag per person included in the 4-fish aggregate bag limit.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 2, 4, 24, null, 'total_length', null, 'Inside the 4-grouper aggregate.', false, 60),
  ('red_grouper', null, 'la-gulf', 'salt', 'bag_limit', 'Red grouper: 20” min total length; not more than 2 red grouper per person included in the 4-fish aggregate bag limit.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 2, 4, 20, null, 'total_length', null, 'Inside the 4-grouper aggregate.', false, 60),
  ('scamp', null, 'la-gulf', 'salt', 'min_size', 'Scamp: 16” min total length (inside the 4-fish daily grouper aggregate).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, 16, null, 'total_length', null, null, false, 60),
  ('goliath_grouper', null, 'la-gulf', 'salt', 'prohibited', 'GOLIATH & NASSAU grouper: Take Prohibited; Take/Possession Prohibited. (Goliath grouper also appears on the federally listed prohibited species list.)', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90),
  ('mutton_snapper', null, 'la-gulf', 'salt', 'bag_limit', 'SNAPPERS: Mutton — 18” min total length; within the 10-fish snapper aggregate with no more than 5 mutton snapper per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 5, 10, 18, null, 'total_length', null, 'Inside the 10-snapper aggregate (gray/mutton/yellowtail/cubera/queen/blackfin/silk/wenchman).', false, 60),
  ('gray_snapper', null, 'la-gulf', 'salt', 'bag_limit', 'Cubera, Gray (mangrove) & Yellowtail snapper: 12” min total length; 10 daily per person in aggregate (no more than 5 mutton inside the ten).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 10, 20, 12, null, 'total_length', null, null, false, 60),
  ('lane_snapper', null, 'la-gulf', 'salt', 'bag_limit', 'LANE: 8” min total length; 20 daily per person in aggregate, with no more than 1 gray triggerfish and not more than 10 vermilion snapper per person included in the bag limit.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 20, 40, 8, null, 'total_length', null, '20-reef aggregate w/ gray trigger + vermilion caps.', false, 60),
  ('vermilion_snapper', null, 'la-gulf', 'salt', 'bag_limit', 'VERMILION snapper: 10” min total length; inside the 20-fish aggregate, no more than 10 vermilion per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 10, 20, 10, null, 'total_length', null, null, false, 60),
  ('lesser_amberjack', null, 'la-gulf', 'salt', 'bag_limit', 'AMBERJACK — LESSER & BANDED RUDDERFISH: 14-22” fork length slot limit; 5 daily per person in aggregate.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 5, 10, 14, 22, 'fork_length', null, null, false, 60),
  ('hogfish', null, 'la-gulf', 'salt', 'bag_limit', 'HOGFISH: 14” min fork length; 5 daily per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 5, 10, 14, null, 'fork_length', null, null, false, 60),
  ('tripletail', null, 'la-gulf', 'salt', 'bag_limit', 'TRIPLETAIL: 18” min total length; 5 daily per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 5, 10, 18, null, 'total_length', null, null, false, 60),
  ('almaco_jack', null, 'la-gulf', 'salt', 'bag_limit', 'ALMACO JACK: No size limit; 20 daily per person in aggregate (with tilefish).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 20, 40, null, null, null, null, null, false, 60),
  ('blue_marlin', null, 'la-gulf', 'salt', 'min_size', 'MARLIN — BLUE MARLIN: 99” min lower jaw fork length; No Bag or Possession Limit (HMS permit required).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, 99, null, 'alternate_total_length', null, 'LJFL; HMS permit.', false, 90),
  ('white_marlin', null, 'la-gulf', 'salt', 'min_size', 'WHITE MARLIN: 66” min lower jaw fork length; No Bag or Possession Limit.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, 66, null, 'alternate_total_length', null, 'LJFL.', false, 90),
  ('sailfish', null, 'la-gulf', 'salt', 'min_size', 'SAILFISH: 63” min lower jaw fork length; No Bag or Possession Limit.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, 63, null, 'alternate_total_length', null, 'LJFL.', false, 90),
  ('swordfish', null, 'la-gulf', 'salt', 'bag_limit', 'SWORDFISH: 47” Lower Jaw Fork Length (LJFL) or 25” cleithrum to caudal keel (CK); 1 per person; no more than 4 per vessel trip; may not be transferred between vessels.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 1, 1, 47, null, 'alternate_total_length', null, '≤4 per vessel trip.', false, 90),
  ('yellowfin_tuna', null, 'la-gulf', 'salt', 'bag_limit', 'TUNA — YELLOWFIN: 27” min curved fork length; 3 daily per person.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, 3, 6, 27, null, 'fork_length', null, 'Curved fork length.', false, 60),
  (null, null, 'la-gulf', 'salt', 'note', 'SHARKS (Louisiana 2025): Atlantic sharpnose & bonnethead — no size, 1 daily per person. Blacktip & bull — no size, no bag limit (note: regulations differ in federal waters). Other sharks (except prohibited, silky and sandbar): 54” min fork length; 1 in aggregate per vessel per trip — no silky or sandbar sharks. Finning is prohibited within and without Louisiana waters. Prohibited sharks: Atlantic angel, basking, bigeye sand tiger, bigeye sixgill, bigeye thresher, bignose, Caribbean reef, Caribbean sharpnose, dusky, Galapagos, longfin mako, narrowtooth, night, sand tiger, sevengill, sixgill, shortfin mako, smalltail, whale and white.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 60),
  (null, null, 'la-gulf', 'salt', 'gear', 'Recreational anglers onboard a vessel to fish for or possess Gulf reef fish in the Gulf EEZ must possess onboard and use: non-stainless steel circle hooks (when fishing with natural baits for reef fish); at least one dehooking device; a descending device or venting tool rigged and ready for use.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet, Required Onboard Gear)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, null, null, null, 'boat', null, false, 60),
  (null, null, 'la-gulf', 'salt', 'note', 'A no-fee Recreational Offshore Landing Permit (ROLP) is required of all anglers to possess tunas, billfish, swordfish, amberjacks, groupers, hinds, snappers, dolphinfish, wahoo, cobia and gray triggerfish (charter clients on a permitted captain''s trip and under-18 anglers are exempt).', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, null, null, null, 'boat', null, false, 60),
  (null, null, 'la-gulf', 'salt', 'prohibited', 'Threatened/endangered/prohibited species are off limits for fishing or recreational take (release immediately unharmed if incidentally caught): all whales, dolphin (mammal), goliath grouper, Gulf sturgeon, largetooth sawfish, Nassau grouper, sea turtles, smalltooth sawfish, West Indian manatee, and the prohibited shark list.', 'https://www.wlf.louisiana.gov/assets/Resources/Publications/Regulations/25LAFW.pdf', 'LDWF — 2025 Louisiana Recreational Fishing Regulations (official booklet)', '2025-08-20', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90);

insert into public.reg_pack (id, version, published_at, notes) values ('mississippi-2026-09-01', 2, '2026-09-01T12:00:00Z', 'Mississippi (MDMR Recreational Catch Limits card): v2 = FULL digest — inshore, reef, pelagic and shark tables verbatim. Red snapper season announced annually (Tails n'' Scales reporting legal). State waters for for-hire extend 9 nm south of the barrier islands; federal Gulf rules apply beyond.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

