  ('speckled_hind', null, 'ms-gulf', 'salt', 'bag_limit', 'Speckled Hind: No minimum size; 1 per vessel (4 Grouper Aggregate applies).', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, 1, 1, null, null, null, 'boat', 'Per VESSEL.', false, 60),
  ('goliath_grouper', null, 'ms-gulf', 'salt', 'prohibited', 'Goliath Grouper: No Take. Nassau Grouper: No Take.', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90),
  ('hogfish', null, 'ms-gulf', 'salt', 'bag_limit', 'Hogfish: 14 FL minimum; 5 bag/possession.', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, 5, 5, 14, null, 'fork_length', null, null, false, 60),
  ('lesser_amberjack', null, 'ms-gulf', 'salt', 'bag_limit', 'Lesser Amberjack and Banded Rudderfish: 14 FL to 22 FL; 5 bag/possession; 5 Fish Aggregate applies.', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, 5, 5, 14, 22, 'fork_length', null, null, false, 60),
  ('yellowfin_tuna', null, 'ms-gulf', 'salt', 'bag_limit', 'Yellowfin Tuna: 27 CFL minimum; 3 bag/possession.', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, 3, 3, 27, null, 'fork_length', null, 'Curved fork length.', false, 60),
  ('blue_marlin', null, 'ms-gulf', 'salt', 'note', 'Blue Marlin: 99 Lower Jaw FL, no limit. White Marlin: 66 Lower Jaw FL, no limit. Sailfish: 63 Lower Jaw FL, no limit. Swordfish: 47 Lower Jaw FL, no limit. Longbill Spearfish: No Take.', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, null, null, 99, null, 'alternate_total_length', null, 'LJFL minima; HMS permits per federal rules.', false, 90),
  (null, null, 'ms-gulf', 'salt', 'note', 'Sharks (MDMR card): Large Coastals and Pelagics (blacktip, spinner, bull, tiger, lemon, nurse, scalloped/great/smooth hammerhead, shortfin mako, porbeagle, thresher, blue, oceanic whitetip): 37 TL minimum; 1 per person up to 3 per vessel. Small Coastals (Atlantic sharpnose, finetooth, blacknose, bonnethead): 25 TL minimum; 4 bag/possession. Prohibited from harvest: Sand Tiger, Bigeye Sand Tiger, Whale, Basking, White, Dusky, Bignose, Galapagos, Night, Caribbean Reef, Narrowtooth, Caribbean Sharpnose, Smalltail, Atlantic Angel, Longfin Mako, Bigeye Thresher, Sevengill, Sixgill, Bigeye Sixgill, Sandbar, and Silky.', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 60),
  ('dorado', null, 'ms-gulf', 'salt', 'note', 'Dolphin (Mahi Mahi): No Limit; No Limit.', 'https://dmr.ms.gov/recreational-catch-limits/', 'MDMR — Recreational Catch Limits (official quick card)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90);

insert into public.reg_pack (id, version, published_at, notes) values ('alabama-2026-09-01', 2, '2026-09-01T12:00:00Z', 'Alabama (ADCNR Saltwater Recreational Size & Creel Limits card, July 2025 PDF): v2 = FULL digest — every row on the agency card plus the 220-3-.77 shark rule and the announced quota-season snapper mechanism. Snapper Check before landing is law.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

insert into public.reg_rule
  (species_id, reg_group_id, reg_area_id, water_class, kind, verbatim, source_url, source_title, source_updated_at, verified_at, pack_version,
   season_start, season_end, bag_daily, possession_limit, min_size_in, max_size_in, size_measure, platform_scope, depth_note, check_inseason, stale_after_days)
values
  ('spotted_seatrout', null, 'al-gulf', 'salt', 'bag_limit', 'Spotted seatrout (speckled trout): 6 daily per person; 15–22 inch total-length slot; only one spotted seatrout larger than 22 inches may be kept (within the 6-fish bag).', 'https://www.outdooralabama.com/node/2632', 'ADCNR — Seatrout, Flounder Limits Change August 1 (MRD regulation-change release)', '2019-07-02', '2026-09-02', 1,
   null, null, 6, 6, 15, 22, 'total_length', null, 'One fish >22” counts inside the 6.', false, 60),
  ('red_drum', null, 'al-gulf', 'salt', 'bag_limit', 'Red Drum (Redfish): 16” min. - 26” max TL; 3 per person. The July 2025 card carries NO over-slot allowance (the former bull-red exception was removed in the 2025 rule cycle — 16-26 slot only).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 3, 3, 16, 26, 'total_length', null, null, false, 60),
  ('southern_flounder', null, 'al-gulf', 'salt', 'bag_limit', 'Flounder: bag of five per person for recreational anglers; 14 inches total length minimum. The entire month of November is closed to flounder fishing, both recreational and commercial.', 'https://www.outdooralabama.com/node/2632', 'ADCNR — Seatrout, Flounder Limits Change August 1 (agency text)', '2019-07-02', '2026-09-02', 1,
   null, null, 5, 5, 14, null, 'total_length', null, 'Closed all November.', false, 60),
  ('southern_flounder', null, 'al-gulf', 'salt', 'season', 'The entire month of November is closed to flounder fishing, both recreational and commercial (November is when flounder migrate to the Gulf of Mexico to spawn).', 'https://www.outdooralabama.com/node/2632', 'ADCNR — Seatrout, Flounder Limits Change August 1 (agency text)', '2019-07-02', '2026-09-02', 1,
   '2026-11-01', '2026-11-30', null, null, null, null, null, null, null, false, 60),
  ('sheepshead', null, 'al-gulf', 'salt', 'bag_limit', 'Sheepshead: 12” min. FL; 8 per person (reduced from 10 in 2025 due to increased fishing pressure).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 8, 8, 12, null, 'fork_length', null, null, false, 60),
  ('red_snapper', null, 'al-gulf', 'salt', 'note', 'Red snapper: Alabama state waters and federal waters opened to private and state-licensed charter anglers on Friday, May 23, 2025; the 2025 private-angler quota was 664,552 pounds and the season closed December 31, 2025. The 2026 quota will be 664,552 pounds and MRD will announce the dates for the 2026 fishing season in the spring. Bag while open: 2 fish per person per day; 16-inch minimum. The owner or operator of each vessel landing red snapper in Alabama is required by law to complete one landing report per vessel trip of their harvested red snapper through Snapper Check prior to removing the fish from the boat.', 'https://www.outdooralabama.com/articles/alabamas-red-snapper-season-continues-through-december-31', 'ADCNR — Alabama’s Red Snapper Season Continues Through December 31 (2025-12-22)', '2025-12-22', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, 'Season dates announced each spring; Snapper Check report required BEFORE landing.', true, 14),
  ('king_mackerel', null, 'al-gulf', 'salt', 'bag_limit', 'King Mackerel: 24” min. FL; 3 per person.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 3, 3, 24, null, 'fork_length', null, null, false, 60),
  ('spanish_mackerel', null, 'al-gulf', 'salt', 'bag_limit', 'Spanish Mackerel: none (no size limit); 15 per person.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 15, 15, null, null, null, null, null, false, 60),
  ('gray_triggerfish', null, 'al-gulf', 'salt', 'bag_limit', 'Gray triggerfish: 1 per person per day; 15-inch fork length minimum (Alabama creel card); when the season is open triggerfish must be reported in Snapper Check.', 'https://www.outdooralabama.com/fishing/saltwater-fishing-and-reports', 'ADCNR — saltwater fishing reports & limits', null, '2026-09-02', 1,
   null, null, 1, 1, 15, null, 'fork_length', null, 'Snapper Check when season open.', true, 60),
  ('cobia', null, 'al-gulf', 'salt', 'bag_limit', 'Cobia (Ling): 36” min. FL; 1 per person, not to exceed 2 per vessel.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 1, 1, 36, null, 'fork_length', null, null, false, 60),
  (null, null, 'al-gulf', 'salt', 'gear', 'All vessels fishing for reef fish in federal waters are required to have a venting tool or descending device rigged and ready to use.', 'https://www.outdooralabama.com/articles/2025-red-snapper-season-modified-provide-increased-fishing-opportunities', 'ADCNR — 2025 Red Snapper Season announcement', '2025-03-13', '2026-09-02', 1,
   null, null, null, null, null, null, null, 'boat', null, false, 60),
  ('goliath_grouper', null, 'al-gulf', 'salt', 'prohibited', 'Goliath grouper and Nassau grouper are prohibited from harvest (Alabama and federal rules).', 'https://www.outdooralabama.com/fishing/saltwater-fishing-and-reports', 'ADCNR — saltwater fishing reports & limits', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90),
  ('florida_pompano', null, 'al-gulf', 'salt', 'bag_limit', 'Florida Pompano: 12” min. TL; 3 per person.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 3, 3, 12, null, 'total_length', null, null, false, 60),
  ('gag_grouper', null, 'al-gulf', 'salt', 'bag_limit', 'Gag Grouper: 24” min TL; 2 per person (mixed species grouper aggregate creel limit: 4 per person; no more than 2 red and 2 gag grouper may be included in the grouper aggregate). Alabama state waters open and close along with federal regulations for this species.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 2, 2, 24, null, 'total_length', null, '4-grouper aggregate; state follows federal open/close.', true, 60),
  ('red_grouper', null, 'al-gulf', 'salt', 'bag_limit', 'Red Grouper: 20” min TL; 2 per person (grouper aggregate 4; ≤2 red).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 2, 2, 20, null, 'total_length', null, null, true, 60),
  ('black_grouper', null, 'al-gulf', 'salt', 'bag_limit', 'Black Grouper: 24” min TL; 4 per person (grouper aggregate 4).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 4, 4, 24, null, 'total_length', null, null, true, 60),
  ('scamp', null, 'al-gulf', 'salt', 'bag_limit', 'Scamp: 16” min TL; 4 per person (grouper aggregate 4).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 4, 4, 16, null, 'total_length', null, null, true, 60),
  ('greater_amberjack', null, 'al-gulf', 'salt', 'bag_limit', 'Greater Amberjack: 34” min FL; 1 per person. Alabama state waters open and close along with federal regulations for this species.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 1, 1, 34, null, 'fork_length', null, 'Snapper Check reporting applies.', true, 60),
  ('striped_bass', null, 'al-gulf', 'salt', 'bag_limit', 'Striped Bass: 16” min TL; 2 per person (only two striped bass are allowed within MRD jurisdiction).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 2, 2, 16, null, 'total_length', null, 'MRD jurisdiction only.', false, 60),
  ('lesser_amberjack', null, 'al-gulf', 'salt', 'bag_limit', 'Lesser Amberjack & Banded Rudderfish: 14” - 22” FL; Reef Fish Aggregate (20-fish aggregate creel limit for reef fish species without other bag limits — grunts, porgies, gray triggerfish, lane snapper, etc.).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 20, 20, 14, 22, 'fork_length', null, 'Inside the 20 reef-fish aggregate.', false, 60),
  ('yellowfin_tuna', null, 'al-gulf', 'salt', 'bag_limit', 'Yellowfin Tuna: 27” min CFL; 3 per person. Bigeye Tuna: 27” min CFL; no creel limit.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 3, 3, 27, null, 'fork_length', null, 'CFL.', false, 60),
  ('common_snook', null, 'al-gulf', 'salt', 'bag_limit', 'Snook: 28” min TL; 1 per person (2025 rule).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 1, 1, 28, null, 'total_length', null, null, false, 60),
  ('vermilion_snapper', null, 'al-gulf', 'salt', 'bag_limit', 'Vermilion Snapper (beeliner): 10” min. TL; 10 per person. Alabama state waters open and close along with federal regulations.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 10, 10, 10, null, 'total_length', null, null, false, 60),
  ('lane_snapper', null, 'al-gulf', 'salt', 'bag_limit', 'Lane Snapper: 10” min. TL; Reef Fish aggregate (20 fish aggregate for reef species without other limits). 2025 change: minimum size increased to 10 inches TL to align with federal.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 20, 20, 10, null, 'total_length', null, null, false, 60),
  ('gray_snapper', null, 'al-gulf', 'salt', 'bag_limit', 'Gray Snapper (mangrove, black): 12” min. TL; 10 per person. Alabama state waters open and close along with federal regulations.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 10, 10, 12, null, 'total_length', null, null, false, 60),
  ('atlantic_tarpon', null, 'al-gulf', 'salt', 'note', 'Tarpon: 60” min. TL; $67.00 tag required to possess, kill or harvest each tarpon.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, null, null, 60, null, 'total_length', null, 'Harvest only with the $67 tag.', false, 60),
  (null, null, 'al-gulf', 'salt', 'note', 'Sharks (Alabama card): Atlantic sharpnose and bonnethead — no size limit, 1 per person per day each. Great, smooth and scalloped hammerhead — 78” min FL, 1 per person per day. All other shark species — 54” min FL, 1 per person per day. Shortfin mako possession prohibited (2025). Per rule 220-3-.77: it is unlawful within 300 feet of the shoreline, or on a public pier, or on a private pier where an unsafe condition is created, to fish for or target sharks by chumming or bloodbaiting, and it is unlawful to target sharks from any pier or beach in a manner that presents an unsafe condition to others.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 60),
  (null, null, 'al-gulf', 'salt', 'gear', 'Skates and Rays: 3 per person. Full retention when using bow, spear, or gig, and it shall be unlawful to remove the tail from any released skate or ray.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, 3, 3, null, null, null, null, null, false, 60),
  ('striped_mullet', null, 'al-gulf', 'salt', 'note', 'Mullet: Oct. 24 - Dec. 31, 25 mullet per person from the shoreline or 25 per boat; no mullet by cast net or snagging in Theodore Industrial Canal, Dog River, Fowl River, and their tributaries.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, 'Seasonal shore/boat cap Oct 24–Dec 31.', false, 60),
  (null, null, 'al-gulf', 'salt', 'prohibited', 'Prohibited Species: Goliath grouper (jewfish), Nassau grouper, Atlantic angel shark, bigeye sand tiger shark, bigeye sixgill shark, bigeye thresher shark, bignose shark, Caribbean reef shark, Caribbean sharpnose shark, Galapagos shark, narrowtooth shark, night shark, sevengill shark, sixgill shark, dusky shark, longfin mako shark, shortfin mako shark, sand tiger shark, basking shark, whale shark, white shark, smalltail shark, smalltooth sawfish, largetooth sawfish, spotted eagle ray, Atlantic manta, and sandbar shark (unless the fisherman possesses a NOAA Fisheries sandbar shark research permit).', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90),
  (null, null, 'al-gulf', 'salt', 'note', 'A saltwater fishing license is required for ALL persons fishing or possessing fish in saltwater areas of Alabama (residents and non-residents under 16 exempt; residents 65+ exempt but must register with the Alabama Saltwater Angler Registry). A Gulf Reef Fish Endorsement applies to reef fish anglers; Snapper Check reporting is mandatory before landing red snapper, greater amberjack, and gray triggerfish.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 60),
  (null, null, 'al-gulf', 'salt', 'note', 'Captain and crew of Alabama Commercial Party Boats shall not retain bag limits of fish harvested in state waters.', 'https://www.outdooralabama.com/fishing/saltwater-recreational-size-creel-limits', 'ADCNR — Saltwater Recreational Size & Creel Limits (July 2025 card)', '2025-07-01', '2026-09-02', 1,
   null, null, null, null, null, null, null, 'boat', null, false, 60);

insert into public.reg_pack (id, version, published_at, notes) values ('baja-california-2026-09-01', 2, '2026-09-01T12:00:00Z', 'Baja California v2 (CONAPESCA / NOM-017-PESC-1994): federal sport catch ceilings apply nationwide — identical clauses as Baja California Sur. Envelope covers the Pacific coast (Tijuana–Punta Eugenia) and the Upper Gulf side to 28° N.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

insert into public.reg_rule
  (species_id, reg_group_id, reg_area_id, water_class, kind, verbatim, source_url, source_title, source_updated_at, verified_at, pack_version,
   season_start, season_end, bag_daily, possession_limit, min_size_in, max_size_in, size_measure, platform_scope, depth_note, check_inseason, stale_after_days)
values
  (null, null, 'mx-baja-california', 'salt', 'note', '4.7.1 Diez ejemplares diarios por pescador, con la siguiente composición por especie: No más de cinco de una misma especie. (Ten fish per person per day, no more than five of a single species.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 10, 10, null, null, null, null, 'Total-day composite rule; per-species ceilings below.', false, 90),
  ('striped_marlin', null, 'mx-baja-california', 'salt', 'bag_limit', 'Cuando se trate de marlin, pez vela, pez espada y tiburón, el límite máximo por pescador y día será de un solo ejemplar de cualquiera de estas especies, el cual será equivalente a cinco ejemplares de otras especies. (For marlin, sailfish, swordfish or shark: ONE specimen a day of any of these — counting as five of the day''s ten.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 1, 1, null, null, null, null, 'One billfish/shark of ANY of those species per day; counts as 5 of the 10.', false, 90),
  ('sailfish', null, 'mx-baja-california', 'salt', 'bag_limit', 'Cuando se trate de marlin, pez vela, pez espada y tiburón, el límite máximo por pescador y día será de un solo ejemplar de cualquiera de estas especies... (For marlin, sailfish, swordfish or shark: ONE specimen a day of any of these, counting as five of the day''s ten.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 1, 1, null, null, null, null, 'Shared with marlin/shark group — one total.', false, 90),
  ('dorado', null, 'mx-baja-california', 'salt', 'bag_limit', 'En el caso de sábalo, dorado o pez gallo, el límite máximo será de dos ejemplares de dichas especies, el cual será equivalente a cinco ejemplares de otras especies. (For tarpon, dorado or roosterfish: TWO per day from this group, each counting as five of the day''s ten.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 2, 2, null, null, null, null, 'Two TOTAL across tarpon/dorado/roosterfish; each counts as 5 of the 10.', false, 90),
  ('roosterfish', null, 'mx-baja-california', 'salt', 'bag_limit', 'En el caso de sábalo, dorado o pez gallo, el límite máximo será de dos ejemplares de dichas especies... (Tarpon, dorado or roosterfish: two per day from this group, each counting as five of the day''s ten.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 2, 2, null, null, null, null, 'Shared 2/day across the group.', false, 90),
  (null, null, 'mx-baja-california', 'salt', 'note', '4.8 En actividades de pesca deportivo recreativa con embarcaciones cuyos viajes tengan una duración de más de tres días, el número máximo acumulable de ejemplares... será el equivalente a tres días de pesca. (Trips longer than three days may accumulate at most three days'' quota.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, 'boat', null, false, 90),
  (null, null, 'mx-baja-california', 'salt', 'gear', '4.9 La pesca subacuática tendrá como límite máximo de captura cinco ejemplares... por pescador y día. (Spearfishing: five fish per person per day, inside the same composition rules.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 5, 5, null, null, null, 'diver', null, false, 90),
  (null, null, 'mx-baja-california', 'salt', 'note', '4.10 ...sin perjuicio de que pueda pescar un mayor número de ejemplares a condición de que los organismos que excedan a dichas cuotas, sean devueltos a su medio natural en buenas condiciones de sobrevivencia («captura y liberación»). (You may continue fishing past quota if the extras are released in good condition — legal catch-and-release.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90),
  (null, null, 'mx-baja-california', 'salt', 'note', 'CONAPESCA Guía de Pesca Deportiva: las especies marlin, pez vela, pez espada, sábalo, pez gallo y pez dorado están destinadas exclusivamente a la pesca deportiva dentro de una franja de 50 millas náuticas; prohibido el desembarco de ejemplares fileteados. (Billfish, tarpon, roosterfish and dorado are sport-only inside 50 nm; you may not land fish already filleted.)', 'https://www.gob.mx/conapesca/documentos/guia-de-pesca-deportiva?state=published', 'CONAPESCA — Guía de Pesca Deportiva', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90),
  (null, null, 'mx-baja-california', 'salt', 'note', 'La práctica de la pesca deportivo recreativa requiere permiso/licencia de la CONAPESCA... la pesca deportiva comercializable... está prohibida. (A Mexican sport-fishing permit is required for every person fishing; selling sport-caught fish is prohibited. Buy permits via CONAPESCA/authorized dealers.)', 'https://www.gob.mx/conapesca/documentos/guia-de-pesca-deportiva?state=published', 'CONAPESCA — Guía de Pesca Deportiva', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 90),
  ('blue_marlin', null, 'mx-baja-california', 'salt', 'bag_limit', 'Cuando se trate de marlin, pez vela, pez espada y tiburón, el límite máximo por pescador y día será de un solo ejemplar de cualquiera de estas especies... (Blue marlin: ONE billfish/shark total of any of the four species per day, counting as five of the day''s ten.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 1, 1, null, null, null, null, 'Shared with marlin/sailfish/shark group — one total.', false, 90),
  (null, null, 'mx-baja-california', 'salt', 'note', 'Cuando se trate de marlin, pez vela, pez espada y tiburón, el límite máximo por pescador y día será de un solo ejemplar de cualquiera de estas especies (sharks share the one-per-day billfish/shark ceiling, counting as five of the day''s ten).', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 1, 1, null, null, null, null, 'Billfish + shark composite.', false, 90),
  (null, null, 'mx-baja-california', 'salt', 'note', '4.7.2 Tratándose de especies de agua dulce, el límite máximo permisible será de cinco ejemplares por pescador por día. (Freshwater species: five per person per day.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, 5, 5, null, null, null, null, 'Continental (fresh) waters tier.', false, 90),
  (null, null, 'mx-baja-california', 'salt', 'note', '4.11 La práctica de la pesca deportivo recreativa queda sujeta a las tallas y pesos mínimos de captura por especie y zona, que establezca la Secretaría... medidas que se notificarán mediante avisos publicados en el Diario Oficial de la Federación. (Minimum sizes/weights by species and zone are set by DOF notices — check the current Diario Oficial notice before keeping unusual species.)', 'https://www.gob.mx/cms/uploads/attachment/file/311370/NOM_017_PESC.pdf', 'NORMA Oficial Mexicana NOM-017-PESC-1994 (DOF) — pesca deportivo-recreativa', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 60);

insert into public.reg_pack (id, version, published_at, notes) values ('baja-california-sur-2026-09-01', 2, '2026-09-01T12:00:00Z', 'Baja California Sur v2 (CONAPESCA / NOM-017-PESC-1994): federal sport catch ceilings; same clauses as Baja California (no state-level catch-limit divergence found — state differences are in licensing/boat permits, not bags). Envelope covers La Paz to Cabo San Lucas.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

